/// 复装流程 SOP（金属弹壳，单动式压机顺序），依据 NRA 七步法、NIJ 复装流程模块、
/// Hornady / Speer / Lyman 各手册通用流程、Alliant 与 RemArms 安全规程整理。
const List<String> reloadSopSteps = [
  '查手册定配方：确认口径、弹头型号与重量、火药型号，翻到手册对应章节抄下起始装药、最大装药、COL、底火与弹壳型号；工作台只留本次要用的火药和底火各一种；换弹头、换火药或底火批号、换枪都必须重查重测。',
  '检查弹壳：逐发检查颈部裂纹、壳身裂纹、底火窝松动、壳口损伤、底部拉伸环，有问题的报废；军用弹壳注意底火窝压接，需先去压接；军用弹壳起始装药再低 10–15%。',
  '清洁弹壳：滚筒或振动抛光去除污垢与氧化层，清洁后便于发现裂纹；检查介质没有残留在壳内或底火窝里。',
  '润滑、退底火与整形：瓶形壳整形前必须润滑，整形模恢复外形并顶出旧底火；擦净润滑剂，量壳长，超规的修整到手册长度并给壳口内外倒角、去毛刺。',
  '底火窝处理与装底火：清理底火窝，底火型号与手册一致（手枪/步枪、大/小、普通/马格努姆不可混用）；压入深度与壳底齐平或略低，不得凸出。',
  '装药：秤先校准，量出起始装药倒入弹壳；装药后、装弹头前必须目视检查每一个弹壳的药面高度，防双重装药，也防漏装药；连续装药时每 10 发复核一次秤，防止量粉器漂移。',
  '装弹头：按手册 COL 坐入弹头，坐深不得短于手册值；弹头不歪斜、不刮铜屑，刮屑说明壳口倒角不足，退回整形步骤处理。',
  '压接：半自动手枪弹与管状弹仓步枪弹做锥形压接消除喇叭口；转轮弹与杠杆枪弹多用滚压接压入弹头环槽；过度压接会损伤弹头、升高膛压。',
  '成品检查：逐发检查底火齐平无凸出、COL 在手册范围内、无弹头歪斜、无壳口裂纹；用弹壳量规或卸下枪管做入膛检查，确认自由落入、自由落出。',
  '试射梯度：从起始装药起递增试射（手枪弹每档加 0.1gr、步枪弹每档加 0.5gr，Lyman 手册常用增量），每档 5 发，记下每档初速、散布与压力迹象；出现异常压力迹象立即停止，不再往上加。',
  '标识、记录与归档：成品盒贴标签（口径、弹头、火药与装药量、COL、底火、日期）；每批完整记一条：弹头、火药与批号、底火与批号、弹壳品牌与使用次数、装药量、COL、试射枪械、初速、散布、天气与备注；换批号、换枪必须另起一批重测。',
];

